module chess_rook_attacker(\n    input wire [47:0] rook_data,\n    input wire [31:0] move_data,\n    input wire [1:0] k,\n    input wire [1:0] p,\n    output reg [15:0] result0,\n    output reg [15:0] result1,\n    output reg [15:0] result2,\n    output reg [15:0] result3\n);\n\n    // Extract rook parameters\n    wire [1:0] rook0_row = rook_data[1:0];\n    wire [1:0] rook0_col = rook_data[3:2];\n    wire [7:0] rook0_power = rook_data[11:4];\n    \n    wire [1:0] rook1_row = rook_data[13:12];\n    wire [1:0] rook1_col = rook_data[15:14];\n    wire [7:0] rook1_power = rook_data[23:16];\n    \n    wire [1:0] rook2_row = rook_data[25:24];\n    wire [1:0] rook2_col = rook_data[27:26];\n    wire [7:0] rook2_power = rook_data[35:28];\n\n    // Extract move parameters\n    wire [1:0] move0_src_row = move_data[1:0];\n    wire [1:0] move0_src_col = move_data[3:2];\n    wire [1:0] move0_dst_row = move_data[5:4];\n    wire [1:0] move0_dst_col = move_data[7:6];\n    \n    wire [1:0] move1_src_row = move_data[9:8];\n    wire [1:0] move1_src_col = move_data[11:10];\n    wire [1:0] move1_dst_row = move_data[13:12];\n    wire [1:0] move1_dst_col = move_data[15:14];\n    \n    wire [1:0] move2_src_row = move_data[17:16];\n    wire [1:0] move2_src_col = move_data[19:18];\n    wire [1:0] move2_dst_row = move_data[21:20];\n    wire [1:0] move2_dst_col = move_data[23:22];\n    \n    wire [1:0] move3_src_row = move_data[25:24];\n    wire [1:0] move3_src_col = move_data[27:26];\n    wire [1:0] move3_dst_row = move_data[29:28];\n    wire [1:0] move3_dst_col = move_data[31:30];\n\n    // Calculate initial board state (after rook placements)\n    reg [7:0] row_xor_after_rooks [0:3];\n    reg [7:0] col_xor_after_rooks [0:3];\n    \n    always @(*) begin\n        // Initialize row/col xors\n        row_xor_after_rooks[0] = 8'd0;\n        row_xor_after_rooks[1] = 8'd0;\n        row_xor_after_rooks[2] = 8'd0;\n        row_xor_after_rooks[3] = 8'd0;\n        \n        col_xor_after_rooks[0] = 8'd0;\n        col_xor_after_rooks[1] = 8'd0;\n        col_xor_after_rooks[2] = 8'd0;\n        col_xor_after_rooks[3] = 8'd0;\n        \n        // Process rook0 if (0 < k)\n        if (2'd0 < k) begin\n            row_xor_after_rooks[rook0_row] = row_xor_after_rooks[rook0_row] ^ rook0_power;\n            col_xor_after_rooks[rook0_col] = col_xor_after_rooks[rook0_col] ^ rook0_power;\n        end\n        \n        // Process rook1 if (1 < k)\n        if (2'd1 < k) begin\n            row_xor_after_rooks[rook1_row] = row_xor_after_rooks[rook1_row] ^ rook1_power;\n            col_xor_after_rooks[rook1_col] = col_xor_after_rooks[rook1_col] ^ rook1_power;\n        end\n        \n        // Process rook2 if (2 < k)\n        if (2'd2 < k) begin\n            row_xor_after_rooks[rook2_row] = row_xor_after_rooks[rook2_row] ^ rook2_power;\n            col_xor_after_rooks[rook2_col] = col_xor_after_rooks[rook2_col] ^ rook2_power;\n        end\n    end\n\n    // Function to count attacked fields based on row/col XOR values\n    function automatic [15:0] count_attacked_fields(\n        input [7:0] row_xor [0:3],\n        input [7:0] col_xor [0:3]\n    );\n    begin\n        count_attacked_fields = 16'd0;\n        \n        // Manually unroll loop for (row=0; row<4; row++)\n        if ((row_xor[0] ^ col_xor[0]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[0] ^ col_xor[1]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[0] ^ col_xor[2]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[0] ^ col_xor[3]) != 8'd0) count_attacked_fields += 16'd1;\n        \n        if ((row_xor[1] ^ col_xor[0]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[1] ^ col_xor[1]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[1] ^ col_xor[2]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[1] ^ col_xor[3]) != 8'd0) count_attacked_fields += 16'd1;\n        \n        if ((row_xor[2] ^ col_xor[0]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[2] ^ col_xor[1]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[2] ^ col_xor[2]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[2] ^ col_xor[3]) != 8'd0) count_attacked_fields += 16'd1;\n        \n        if ((row_xor[3] ^ col_xor[0]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[3] ^ col_xor[1]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[3] ^ col_xor[2]) != 8'd0) count_attacked_fields += 16'd1;\n        if ((row_xor[3] ^ col_xor[3]) != 8'd0) count_attacked_fields += 16'd1;\n    end\n    endfunction\n\n    // Stage 0 calculations (after initial rook placement)\n    wire [15:0] stage0_count = count_attacked_fields(row_xor_after_rooks, col_xor_after_rooks);\n\n    // Stage 1 calculations (after move0)\n    reg [7:0] row_xor_after_move0 [0:3];\n    reg [7:0] col_xor_after_move0 [0:3];\n    wire valid_move0 = (p > 2'd0);\n    wire [7:0] power_move0 = row_xor_after_rooks[move0_src_row] ^ col_xor_after_rooks[move0_src_col];\n    \n    always @(*) begin\n        row_xor_after_move0[0] = row_xor_after_rooks[0];\n        row_xor_after_move0[1] = row_xor_after_rooks[1];\n        row_xor_after_move0[2] = row_xor_after_rooks[2];\n        row_xor_after_move0[3] = row_xor_after_rooks[3];\n        \n        col_xor_after_move0[0] = col_xor_after_rooks[0];\n        col_xor_after_move0[1] = col_xor_after_rooks[1];\n        col_xor_after_move0[2] = col_xor_after_rooks[2];\n        col_xor_after_move0[3] = col_xor_after_rooks[3];\n        \n        if (valid_move0) begin\n            row_xor_after_move0[move0_src_row] = row_xor_after_rooks[move0_src_row] ^ power_move0;\n            row_xor_after_move0[move0_dst_row] = row_xor_after_rooks[move0_dst_row] ^ power_move0;\n            \n            col_xor_after_move0[move0_src_col] = col_xor_after_rooks[move0_src_col] ^ power_move0;\n            col_xor_after_move0[move0_dst_col] = col_xor_after_rooks[move0_dst_col] ^ power_move0;\n        end\n    end\n    \n    wire [15:0] stage1_count = count_attacked_fields(row_xor_after_move0, col_xor_after_move0);\n\n    // Stage 2 calculations (after move1)\n    reg [7:0] row_xor_after_move1 [0:3];\n    reg [7:0] col_xor_after_move1 [0:3];\n    wire valid_move1 = (p > 2'd1);\n    wire [7:0] power_move1 = row_xor_after_move0[move1_src_row] ^ col_xor_after_move0[move1_src_col];\n    \n    always @(*) begin\n        row_xor_after_move1[0] = row_xor_after_move0[0];\n        row_xor_after_move1[1] = row_xor_after_move0[1];\n        row_xor_after_move1[2] = row_xor_after_move0[2];\n        row_xor_after_move1[3] = row_xor_after_move0[3];\n        \n        col_xor_after_move1[0] = col_xor_after_move0[0];\n        col_xor_after_move1[1] = col_xor_after_move0[1];\n        col_xor_after_move1[2] = col_xor_after_move0[2];\n        col_xor_after_move1[3] = col_xor_after_move0[3];\n        \n        if (valid_move1) begin\n            row_xor_after_move1[move1_src_row] = row_xor_after_move0[move1_src_row] ^ power_move1;\n            row_xor_after_move1[move1_dst_row] = row_xor_after_move0[move1_dst_row] ^ power_move1;\n            \n            col_xor_after_move1[move1_src_col] = col_xor_after_move0[move1_src_col] ^ power_move1;\n            col_xor_after_move1[move1_dst_col] = col_xor_after_move0[move1_dst_col] ^ power_move1;\n        end\n    end\n    \n    wire [15:0] stage2_count = count_attacked_fields(row_xor_after_move1, col_xor_after_move1);\n\n    // Stage 3 calculations (after move2)\n    reg [7:0] row_xor_after_move2 [0:3];\n    reg [7:0] col_xor_after_move2 [0:3];\n    wire valid_move2 = (p > 2'd2);\n    wire [7:0] power_move2 = row_xor_after_move1[move2_src_row] ^ col_xor_after_move1[move2_src_col];\n    \n    always @(*) begin\n        row_xor_after_move2[0] = row_xor_after_move1[0];\n        row_xor_after_move2[1] = row_xor_after_move1[1];\n        row_xor_after_move2[2] = row_xor_after_move1[2];\n        row_xor_after_move2[3] = row_xor_after_move1[3];\n        \n        col_xor_after_move2[0] = col_xor_after_move1[0];\n        col_xor_after_move2[1] = col_xor_after_move1[1];\n        col_xor_after_move2[2] = col_xor_after_move1[2];\n        col_xor_after_move2[3] = col_xor_after_move1[3];\n        \n        if (valid_move2) begin\n            row_xor_after_move2[move2_src_row] = row_xor_after_move1[move2_src_row] ^ power_move2;\n            row_xor_after_move2[move2_dst_row] = row_xor_after_move1[move2_dst_row] ^ power_move2;\n            \n            col_xor_after_move2[move2_src_col] = col_xor_after_move1[move2_src_col] ^ power_move2;\n            col_xor_after_move2[move2_dst_col] = col_xor_after_move1[move2_dst_col] ^ power_move2;\n        end\n    end\n    \n    wire [15:0] stage3_count = count_attacked_fields(row_xor_after_move2, col_xor_after_move2);\n\n    // Stage 4 calculations (disables beyond max p)\n    always @(*) begin\n        result0 = (p > 2'd0) ? stage1_count : 16'd0;\n        result1 = (p > 2'd1) ? stage2_count : 16'd0;\n        result2 = (p > 2'd2) ? stage3_count : 16'd0;\n        result3 = 16'd0;  // p >3 is impossible with 2-bit p\n    end\n\nendmodule